## 1. Paste the Final formulas

In `Final!A1:F1`, enter these headers: **Timestamp, Name, Email, JoinedBefore, Phone, PreferredPark**.

Paste this into `Final!A2` for **email-bearing rows only**:

```gs
=IFNA(FILTER(
  {Raw!I2:I421,Raw!L2:L421,Raw!K2:K421,Raw!G2:G421,Raw!H2:H421,Raw!J2:J421},
  Raw!P2:P421="OK",
  Raw!O2:O421<>"SUPERSEDED",
  Raw!K2:K421<>""
),"")
```

### Include unique submissions with no email

Use this **instead of** the first formula to get both sets of rows in one table:

```gs
=IFNA(FILTER(
  {Raw!I2:I421,Raw!L2:L421,Raw!K2:K421,Raw!G2:G421,Raw!H2:H421,Raw!J2:J421},
  Raw!P2:P421="OK",
  Raw!O2:O421<>"SUPERSEDED",
  ((Raw!K2:K421<>"")+((Raw!K2:K421="")*(Raw!L2:L421<>"")*(Raw!N2:N421="")))>0
),"")
```

This keeps a blank-email row only if it has a name and `N` found no same-name submission within 10 minutes, including matches against rows that *do* have an email. Format `Final!A:A` as **Date time**. Column B will be lowercase because `L` is your normalized name key. If your helpers are on `Clean`, replace `Raw!` with `Clean!`; extend row `421` in the filters **and** helper formulas as responses grow.

### Two helper fixes so the filters work as intended

The original `P` marks **both** rows in a repeated-email group `REVIEW`, so neither can reach `Final`. The original `O` also leaves equal timestamps tied. If your policy is “latest submission per email wins,” use these replacements and fill down:

**`Raw!O2` — latest valid timestamp wins; on a tie, the later sheet row wins:**

```gs
=IF(OR(K2="",NOT(ISNUMBER(I2))),"",
  IF(OR(
    COUNTIFS($K$2:$K$421,K2,$I$2:$I$421,">"&I2)>0,
    COUNTIFS($K$2:K2,K2,$I$2:I2,I2)<COUNTIFS($K$2:$K$421,K2,$I$2:$I$421,I2)
  ),"SUPERSEDED",""))
```

**`Raw!P2` — repeated email is informational; ambiguous blank-email rows still need review:**

```gs
=IF(COUNTA(A2:F2)=0,"",
  IF(OR(G2="REVIEW",H2="REVIEW",NOT(ISNUMBER(I2)),J2="REVIEW",
        AND(K2="",OR(L2="",N2<>""))),
     "REVIEW","OK"))
```

Keep any intentional manual holds when updating `P`. If the latest timestamped submission has a bad phone or an unmapped park, it stays out of `Final`; the filter does **not** silently fall back to an older submission. In your Maya example, row 2 wins the timestamp tie, but it still needs a valid phone before it can appear.

## 2. Apps Script for an automatically rebuilt snapshot

The formulas are simpler for a live view. Use this script if you want `Final` written as values after each form submission. It reads `Raw!A:F` and `ParkMap!A:B`, leaves your helpers alone, and writes a separate `Review` tab with source row numbers and reasons. It **overwrites `Final` and `Review`**, so remove the `Final` spill formula if you switch to the script.

```javascript
function rebuildFinal() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getSheetByName('Raw'), map = ss.getSheetByName('ParkMap');
  const tz = ss.getSpreadsheetTimeZone(), day = 86400000, minutes = 10;
  const text = v => String(v ?? '').trim();
  const key = v => text(v).toLowerCase().replace(/[^a-z]/g, '');
  const body = (s, cols) => s.getLastRow() < 2 ? [] :
    s.getRange(2, 1, s.getLastRow() - 1, cols).getValues();
  const parks = new Map(body(map, 2).map(([k, v]) => [key(k), text(v)]));

  function timestamp(v) {
    if (v instanceof Date) {
      return Date.parse(Utilities.formatDate(v, tz, "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"));
    }
    // Text dates: US M/D/YY(YY) or D-Mon-YYYY, optionally with 24-hour time.
    const s = text(v);
    const a = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4}|\d{2})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/);
    const b = s.match(/^(\d{1,2})-([a-z]{3})-(\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/i);
    const m = a || b;
    if (!m) return NaN;
    const month = a ? +a[1] - 1 :
      'jan feb mar apr may jun jul aug sep oct nov dec'.split(' ').indexOf(b[2].toLowerCase());
    const d = +(a ? a[2] : b[1]);
    let y = +m[3];
    if (m[3].length === 2) y += y < 30 ? 2000 : 1900;
    const [h, min, sec] = m.slice(4).map(x => +(x || 0));
    const t = Date.UTC(y, month, d, h, min, sec), check = new Date(t);
    return month >= 0 && month < 12 && h < 24 && min < 60 && sec < 60 &&
      check.getUTCMonth() === month && check.getUTCDate() === d ? t : NaN;
  }

  const rows = body(raw, 6).flatMap(([ts, nm, em, yn, ph, pk], i) => {
    if (![ts, nm, em, yn, ph, pk].some(v => text(v) !== '')) return [];
    const name = text(nm).toLowerCase().replace(/\s+/g, ' ');
    const email = text(em).toLowerCase(), t = timestamp(ts);
    const joined = /^y(es)?$/i.test(text(yn)) ? 'Yes' :
      /^no?$/i.test(text(yn)) ? 'No' : '';
    const phone = text(ph).replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
    const park = parks.get(key(pk)) || '';
    return [{row: i + 2, t, name, email, joined, phone, park}];
  });

  const latest = new Map(), final = [], review = [];
  for (const r of rows) {
    if (r.email && Number.isFinite(r.t) &&
        (!latest.has(r.email) || r.t >= latest.get(r.email).t)) latest.set(r.email, r);
  }
  for (const r of rows) {
    const issues = [];
    if (!Number.isFinite(r.t)) issues.push('Timestamp');
    if (!r.joined) issues.push('JoinedBefore');
    if (r.phone.length !== 10) issues.push('Phone');
    if (!r.park) issues.push('PreferredPark');
    if (!r.email && (!r.name || rows.some(s =>
      s !== r && s.name === r.name && Math.abs(s.t - r.t) <= minutes * 60000
    ))) issues.push('Blank email: missing name or nearby name match');

    if (issues.length) review.push([r.row, 'REVIEW', issues.join('; ')]);
    else if (!r.email || latest.get(r.email) === r) {
      final.push([r.t / day + 25569, r.name, r.email, r.joined, r.phone, r.park]);
    }
  }

  function write(name, header, data) {
    const s = ss.getSheetByName(name) || ss.insertSheet(name);
    s.clearContents();
    if (name === 'Final' && data.length) {
      s.getRange(2, 1, data.length, 1).setNumberFormat('yyyy-mm-dd hh:mm:ss');
      s.getRange(2, 5, data.length, 1).setNumberFormat('@');
    }
    s.getRange(1, 1, data.length + 1, header.length).setValues([header, ...data]);
  }
  write('Final', ['Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark'], final);
  write('Review', ['Raw row', 'Status', 'Reasons'], review);
}
```

Paste it into **Extensions → Apps Script** and run `rebuildFinal` once to authorize and verify the output. Then add an installable trigger for `rebuildFinal`: **From spreadsheet → On form submit**. If new rows arrive by import rather than through a linked Google Form, use a time-driven trigger instead. The script assumes month-first slash dates; if your text dates are day-first, adjust the parser before enabling the trigger.
